import{_ as s,o as a,c as t,ak as r}from"./chunks/framework.Cq0X4QeM.js";const h=JSON.parse('{"title":"OSCP · Rapports de pentest","description":"Documenter les constats et les preuves techniques.","frontmatter":{"title":"OSCP · Rapports de pentest","description":"Documenter les constats et les preuves techniques."},"headers":[],"relativePath":"oscp/rapport.md","filePath":"oscp/rapport.md"}'),n={name:"oscp/rapport.md"};function i(o,e,p,l,c,d){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="oscp-·-rapports-de-pentest" tabindex="-1">OSCP · Rapports de pentest <a class="header-anchor" href="#oscp-·-rapports-de-pentest" aria-label="Permalink to &quot;OSCP · Rapports de pentest&quot;">​</a></h1><p>Documenter les constats et les preuves techniques.</p><h2 id="prise-de-notes-et-rapports" tabindex="-1">Prise de notes et rapports <a class="header-anchor" href="#prise-de-notes-et-rapports" aria-label="Permalink to &quot;Prise de notes et rapports&quot;">​</a></h2><p>Structurer les notes, les constats et les preuves techniques.</p><h2 id="captures-d-ecran" tabindex="-1">Captures d&#39;écran <a class="header-anchor" href="#captures-d-ecran" aria-label="Permalink to &quot;Captures d&#39;écran&quot;">​</a></h2><p>Conserver des captures lisibles pour appuyer les constats.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Capturer les écrans utiles depuis Windows.</p><h3 id="kali-linux" tabindex="-1">Kali Linux <a class="header-anchor" href="#kali-linux" aria-label="Permalink to &quot;Kali Linux&quot;">​</a></h3><p>Réaliser les captures depuis Kali Linux.</p><p><strong>Paramètres et repères :</strong><code>gnome-screenshot</code></p><h3 id="bonnes-pratiques-pour-les-captures-d-ecran" tabindex="-1">Bonnes pratiques pour les captures d’écran <a class="header-anchor" href="#bonnes-pratiques-pour-les-captures-d-ecran" aria-label="Permalink to &quot;Bonnes pratiques pour les captures d’écran&quot;">​</a></h3><p>Conserver le contexte nécessaire à la compréhension de chaque preuve.</p><p><strong>Paramètres et repères :</strong><code>sql_injection_vuln_example.png</code></p><h2 id="elements-essentiels-d-un-rapport" tabindex="-1">Éléments essentiels d’un rapport <a class="header-anchor" href="#elements-essentiels-d-un-rapport" aria-label="Permalink to &quot;Éléments essentiels d’un rapport&quot;">​</a></h2><p>Présenter le périmètre, les constats, les preuves et les recommandations.</p><h2 id="mise-en-forme-du-rapport" tabindex="-1">Mise en forme du rapport <a class="header-anchor" href="#mise-en-forme-du-rapport" aria-label="Permalink to &quot;Mise en forme du rapport&quot;">​</a></h2><p>Organiser le rapport pour faciliter la lecture des résultats.</p><h2 id="rapport-de-conformite-facultatif" tabindex="-1">Rapport de conformité (facultatif) <a class="header-anchor" href="#rapport-de-conformite-facultatif" aria-label="Permalink to &quot;Rapport de conformité (facultatif)&quot;">​</a></h2><p>Relier les constats aux exigences applicables lorsque cela est demandé.</p><h2 id="conserver-des-preuves-verifiables" tabindex="-1">Conserver des preuves vérifiables <a class="header-anchor" href="#conserver-des-preuves-verifiables" aria-label="Permalink to &quot;Conserver des preuves vérifiables&quot;">​</a></h2><p>Une preuve doit préserver son contexte : système, compte de test, date, cible et commande exécutée. Le rapport distingue observation, impact et recommandations.</p><h3 id="empreinte-sha-256-sous-linux" tabindex="-1">Empreinte SHA-256 sous Linux <a class="header-anchor" href="#empreinte-sha-256-sous-linux" aria-label="Permalink to &quot;Empreinte SHA-256 sous Linux&quot;">​</a></h3><p>Calculer l&#39;empreinte d&#39;un fichier de preuve pour contrôler son intégrité sans divulguer son contenu.</p><p class="oscp-command-note">Calculer l’empreinte d’un fichier sous Linux.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FICHIER_PREUV</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="empreinte-sha-256-sous-windows" tabindex="-1">Empreinte SHA-256 sous Windows <a class="header-anchor" href="#empreinte-sha-256-sous-windows" aria-label="Permalink to &quot;Empreinte SHA-256 sous Windows&quot;">​</a></h3><p>Associer une empreinte à chaque capture conservée dans le dossier du rapport.</p><p class="oscp-command-note">Calculer l’empreinte d’une capture avec PowerShell.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-FileHash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Algorithm SHA256 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;CAPTURE&gt;.png&#39;</span></span></code></pre></div><p>Pour structurer les constats, consulter le <a href="https://docs.sysreptor.com/offsec-reporting-with-sysreptor/" target="_blank" rel="noreferrer">guide de rapports OffSec avec SysReptor</a>. Éviter d&#39;exécuter un script d&#39;installation distant sans en examiner le contenu.</p><p><strong>Référence complémentaire :</strong> <a href="https://github.com/krovs/oscp-notes/blob/main/README.md" target="_blank" rel="noreferrer">krovs/oscp-notes</a>.</p><hr><p>Source documentaire : <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">OSCP+ Cheatsheet d&#39;Emmanuel Solis</a>.</p>',34)]))}const m=s(n,[["render",i]]);export{h as __pageData,m as default};
